func (this *Test_org_eclipse_swt_custom_StyledText) Test_getSelection() {
	this.text.SetText("01234567890")
	this.text.SetSelectionPoint(swt.NewPoint(2, 2))
	junit.AssertEquals(swt.NewPoint(2, 2), this.text.GetSelection())
	this.text.SetSelectionPoint(swt.NewPoint(2, 3))
	junit.AssertEquals(swt.NewPoint(2, 3), this.text.GetSelection())
	this.text.SetSelectionPoint(swt.NewPoint(3, 11))
	junit.AssertEquals(swt.NewPoint(3, 11), this.text.GetSelection())
	this.text.SetText("01234567890")
	this.text.SetSelection(4)
	junit.AssertEquals(swt.NewPoint(4, 4), this.text.GetSelection())
	this.text.SetSelection(11)
	junit.AssertEquals(swt.NewPoint(11, 11), this.text.GetSelection())
	this.text.SetSelectionPoint(swt.NewPoint(3, 2))
	junit.AssertEquals(swt.NewPoint(2, 3), this.text.GetSelection())
}

func (this *Test_org_eclipse_swt_custom_StyledText) Test_getSelectionBackground() {
	junit.AssertNotNull(this.text.GetSelectionBackground())
	this.text.SetSelectionBackground(Test_org_eclipse_swt_custom_StyledTextYELLOW)
	junit.AssertEquals(Test_org_eclipse_swt_custom_StyledTextYELLOW, this.text.GetSelectionBackground())
}

func (this *Test_org_eclipse_swt_custom_StyledText) Test_getSelectionCount() {
	this.text.SetText("01234567890")
	junit.AssertEquals(int32(0), int32(this.text.GetSelectionCount()))
	this.text.SetSelectionStartEnd(2, 4)
	junit.AssertEquals(int32(2), int32(this.text.GetSelectionCount()))
	this.text.SetSelectionStartEnd(2, 11)
	junit.AssertEquals(int32(9), int32(this.text.GetSelectionCount()))
	this.text.SetText("0123\n4567890")
	junit.AssertEquals(int32(0), int32(this.text.GetSelectionCount()))
	this.text.SetSelectionStartEnd(2, 4)
	junit.AssertEquals(int32(2), int32(this.text.GetSelectionCount()))
	this.text.SetSelectionStartEnd(2, 12)
	junit.AssertEquals(int32(10), int32(this.text.GetSelectionCount()))
}

func (this *Test_org_eclipse_swt_custom_StyledText) Test_getSelectionCountInBlockSelection() {
	this.text.SetText(this.BlockSelectionTestText())
	this.text.SetSize(1000, 1000)
	this.text.SetBlockSelection(true)
	var lowerRight *swt.Point = this.text.GetLocationAtOffset(jrt.StringLength(this.BlockSelectionTestTextOneLine())*2 + 6)
	this.text.SetBlockSelectionBoundsXYWidthHeight(0, 0, lowerRight.X, lowerRight.Y+1)
	junit.AssertEquals(int32(18+jrt.StringLength(jrt.LineSeparator())*2), int32(this.text.GetSelectionCount()))
}

