	junit.AssertNotNull(this.text.GetSelectionForeground())
	this.text.SetSelectionForeground(Test_org_eclipse_swt_custom_StyledTextRED)
	junit.AssertEquals(Test_org_eclipse_swt_custom_StyledTextRED, this.text.GetSelectionForeground())
